"use client";

import { useState, useCallback, useEffect } from "react";
import Image from "next/image";
import { useLanguage } from "@/src/context/LanguageContext";
import {
  Card,
  CardContent,
} from "@/src/components/ui/card";
import { Button } from "@/src/components/ui/button";
import { Input } from "@/src/components/ui/input";
import {
  Building2,
  Save,
  Plus,
  Trash2,
  Edit2,
  CheckCircle2,
  TrendingUp,
  TrendingDown,
  Receipt,
  Users2,
  Download,
} from "lucide-react";
import { PhoneInput } from "@/src/components/ui/phone-input";
import { cn } from "@/lib/utils";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogFooter,
} from "@/src/components/ui/dialog";
import { Label } from "@/src/components/ui/label";
import { toast } from "react-hot-toast";
import { useIPCAction } from "@/hooks/useIPCAction";

interface Company {
  id: string;
  name: string;
  legalName: string | null;
  taxId: string | null;
  address: string | null;
  email: string | null;
  phone: string | null;
  logoUrl: string | null;
  website: string | null;
  leaderName: string | null;
  legalForm: string | null;
  registrationNumber: string | null;
  sector: string | null;
  description: string | null;
  productsServices: string | null;
  targetMarket: string | null;
  annualRevenue: number | null;
  monthlyRevenue: number | null;
  employeeCount: number | null;
  departments: string | null;
}

interface CompaniesClientProps {
  initialCompanies: any; // Now contains { companies, stats }
}

export default function CompaniesClient({
  initialCompanies,
}: CompaniesClientProps) {
  const { t } = useLanguage();
  const [companies, setCompanies] = useState<Company[]>(initialCompanies?.companies || []);
  const [stats, setStats] = useState(initialCompanies?.stats || {
    totalRevenue: 0,
    totalLoss: 0,
    totalExpenses: 0,
    totalClients: 0
  });
  const [activeCompanyId, setActiveCompanyId] = useState<string | null>(null);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [editingCompany, setEditingCompany] = useState<Company | null>(null);
  const { performAction, loading: actionLoading } = useIPCAction();

  useEffect(() => {
    const userStr = localStorage.getItem("user");
    if (userStr) {
      setActiveCompanyId(JSON.parse(userStr).activeCompanyId);
    }
  }, []);

  const [formData, setFormData] = useState({
    name: "",
    legalName: "",
    taxId: "",
    address: "",
    email: "",
    phone: "",
    logoUrl: "",
    website: "",
    leaderName: "",
    legalForm: "",
    registrationNumber: "",
    sector: "",
    description: "",
    productsServices: "",
    targetMarket: "",
    annualRevenue: "",
    monthlyRevenue: "",
    employeeCount: "",
    departments: "",
  });

  const fetchCompanies = useCallback(async () => {
    // @ts-ignore
    const res = await window.electronAPI.getData("companies");
    if (res.success) {
      setCompanies(res.data.companies);
      setStats(res.data.stats);
    }
  }, []);

  const resetForm = () => {
    setEditingCompany(null);
    setFormData({
      name: "",
      legalName: "",
      taxId: "",
      address: "",
      email: "",
      phone: "",
      logoUrl: "",
      website: "",
      leaderName: "",
      legalForm: "",
      registrationNumber: "",
      sector: "",
      description: "",
      productsServices: "",
      targetMarket: "",
      annualRevenue: "",
      monthlyRevenue: "",
      employeeCount: "",
      departments: "",
    });
  };

  const openEdit = (c: Company) => {
    setEditingCompany(c);
    setFormData({
      name: c.name,
      legalName: c.legalName || "",
      taxId: c.taxId || "",
      address: c.address || "",
      email: c.email || "",
      phone: c.phone || "",
      logoUrl: c.logoUrl || "",
      website: c.website || "",
      leaderName: c.leaderName || "",
      legalForm: c.legalForm || "",
      registrationNumber: c.registrationNumber || "",
      sector: c.sector || "",
      description: c.description || "",
      productsServices: c.productsServices || "",
      targetMarket: c.targetMarket || "",
      annualRevenue: c.annualRevenue?.toString() || "",
      monthlyRevenue: c.monthlyRevenue?.toString() || "",
      employeeCount: c.employeeCount?.toString() || "",
      departments: c.departments || "",
    });
    setIsDialogOpen(true);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    const method = editingCompany ? "update" : "create";
    const params = editingCompany ? [editingCompany.id, formData] : [formData];

    const res = await performAction("companies", method, ...params);

    if (res.success) {
      toast.success(editingCompany ? t("updateStructure") : t("save"));
      setIsDialogOpen(false);
      resetForm();
      fetchCompanies();
      
      // Auto-set as active if this is the first company or none is active
      if (!editingCompany && (!activeCompanyId || companies.length === 0)) {
        setTimeout(() => {
          handleSetActive(res.data.id);
        }, 500);
      }
    }
  };

  const handleDelete = async (id: string, name: string) => {
    if (!confirm(t("deleteStructureWarning"))) return;

    const res = await performAction("companies", "delete", id);

    if (res.success) {
      toast.success("Entreprise supprimée");
      fetchCompanies();
    }
  };

  const handleSetActive = async (companyId: string) => {
    const res = await performAction("companies", "setActive", companyId);
    if (res.success) {
      setActiveCompanyId(companyId);
      const activeCompany = companies.find(c => c.id === companyId);
      // Update localStorage
      const userStr = localStorage.getItem("user");
      if (userStr) {
        const user = JSON.parse(userStr);
        user.activeCompanyId = companyId;
        user.activeCompanyName = activeCompany?.name || "";
        localStorage.setItem("user", JSON.stringify(user));
      }
      toast.success("Entreprise activée");
      window.dispatchEvent(new CustomEvent("session-update"));
    }
  };

  const handleExportStats = async () => {
    setIsExporting(true);
    try {
       const userStr = localStorage.getItem("user");
       const userId = userStr ? JSON.parse(userStr).id : null;
       // @ts-ignore
       const res = await window.electronAPI.getData("export", userId, "overview");
       if (res.success && res.data) {
         const blob = new Blob([res.data], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
         const url = URL.createObjectURL(blob);
         const link = document.createElement("a");
         link.href = url;
         link.download = `overview_export_${new Date().toISOString().split('T')[0]}.xlsx`;
         document.body.appendChild(link);
         link.click();
         document.body.removeChild(link);
         toast.success("Export réussi");
       }
    } catch (error) {
       console.error(error);
       toast.error("Erreur lors de l'export");
    } finally {
       setIsExporting(false);
    }
  };

  const handleLogoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      const res = await performAction("companies", "logo", {
        image: base64,
        companyId: editingCompany?.id,
      });

      if (res.success) {
        setFormData((prev) => ({ ...prev, logoUrl: res.data.logoUrl }));
        window.dispatchEvent(new CustomEvent("session-update"));
        toast.success("Logo uploadé");
      }
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="min-h-full min-w-full bg-background text-foreground p-5 md:p-10 lg:p-16 pt-28 md:pt-28 lg:pt-28 relative pb-20">
      <div className="max-w-6xl mx-auto space-y-10 relative z-10 w-full">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 animate-fade-in-up">
          <div className="space-y-3">
            <div className="flex items-center gap-3">
              <div className="h-1.5 w-10 bg-primary rounded-full shadow-[0_0_10px_rgba(16,185,129,0.5)]" />
              <span className="text-primary font-black text-[10px] uppercase tracking-[0.4em]">
                {t("companySettings")}
              </span>
            </div>
            <h1 className="text-4xl md:text-6xl font-black md:tracking-tighter bg-gradient-to-br from-white via-white to-slate-500 bg-clip-text text-transparent font-sans uppercase">
              {t("companies")}
            </h1>
            <p className="text-muted-foreground text-lg max-w-xl font-sans italic">
              {t("companySettingsDesc")}
            </p>
          </div>

          <div className="flex items-center gap-3 animate-fade-in-up delay-100">
            <Button
              variant="outline"
              disabled={isExporting}
              onClick={handleExportStats}
              className="h-14 px-6 gap-2 font-bold border-white/10 bg-white/5 backdrop-blur-xl hover:bg-white/10 transition-all rounded-2xl"
            >
              <Download className="w-4 h-4" />
              {isExporting ? "Export..." : "Export Stats"}
            </Button>
            <Dialog
              open={isDialogOpen}
              onOpenChange={(open) => {
                setIsDialogOpen(open);
                if (!open) resetForm();
              }}
            >
              <DialogTrigger asChild>
                <Button className="font-black gap-3 px-8 py-6 rounded-2xl bg-primary hover:bg-primary/90 shadow-lg shadow-primary/20 hover:shadow-primary/40 transition-all group overflow-hidden relative h-auto uppercase tracking-widest text-xs">
                  <div className="absolute inset-0 bg-white/10 translate-y-full group-hover:translate-y-0 transition-transform duration-300" />
                  <Plus className="w-5 h-5 relative z-10" />
                  <span className="relative z-10">{t("addStructure")}</span>
                </Button>
              </DialogTrigger>
              <DialogContent className="sm:max-w-[800px] bg-slate-950/90 border border-white/10 text-foreground backdrop-blur-3xl rounded-[2.5rem] shadow-2xl">
                <DialogHeader className="space-y-4">
                  <DialogTitle className="text-3xl font-black tracking-tighter uppercase">
                    {editingCompany ? t("updateStructure") : t("addStructure")}
                  </DialogTitle>
                  <DialogDescription className="text-slate-400 font-sans italic">
                    Renseignez les informations qui apparaîtront sur vos
                    factures et devis.
                  </DialogDescription>
                </DialogHeader>
                <form onSubmit={handleSave} className="space-y-8 py-6">
                  <div className="grid md:grid-cols-2 gap-6">
                    <div className="space-y-3">
                      <Label
                        htmlFor="name"
                        className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1"
                      >
                        Nom / Enseigne commerciale *
                      </Label>
                      <Input
                        id="name"
                        value={formData.name}
                        onChange={(e) =>
                          setFormData({ ...formData, name: e.target.value })
                        }
                        required
                        className="bg-white/5 border-white/10 h-14 rounded-2xl focus:ring-primary/20 focus:border-primary transition-all font-sans"
                      />
                    </div>
                    <div className="space-y-3">
                      <Label
                        htmlFor="legalName"
                        className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1"
                      >
                        Raison Sociale
                      </Label>
                      <Input
                        id="legalName"
                        value={formData.legalName}
                        onChange={(e) =>
                          setFormData({
                            ...formData,
                            legalName: e.target.value,
                          })
                        }
                        className="bg-white/5 border-white/10 h-14 rounded-2xl focus:ring-primary/20 focus:border-primary transition-all font-sans"
                        placeholder="Ex: Ma Société SAS"
                      />
                    </div>
                    <div className="space-y-3">
                      <Label
                        htmlFor="taxId"
                        className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1"
                      >
                        Numéro fiscal
                      </Label>
                      <Input
                        id="taxId"
                        value={formData.taxId}
                        onChange={(e) =>
                          setFormData({ ...formData, taxId: e.target.value })
                        }
                        className="bg-muted/20 border-border/50 h-14 rounded-2xl focus:ring-primary/20 focus:border-primary transition-all font-sans"
                      />
                    </div>
                    <div className="space-y-3">
                      <Label
                        htmlFor="leaderName"
                        className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1"
                      >
                        Nom du dirigeant / fondateur *
                      </Label>
                      <Input
                        id="leaderName"
                        value={formData.leaderName}
                        onChange={(e) =>
                          setFormData({
                            ...formData,
                            leaderName: e.target.value,
                          })
                        }
                        required
                        className="bg-muted/20 border-border/50 h-14 rounded-2xl focus:ring-primary/20 focus:border-primary transition-all font-sans"
                      />
                    </div>
                    <div className="space-y-3">
                      <Label
                        htmlFor="legalForm"
                        className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1"
                      >
                        Forme juridique *
                      </Label>
                      <Input
                        id="legalForm"
                        value={formData.legalForm}
                        onChange={(e) =>
                          setFormData({
                            ...formData,
                            legalForm: e.target.value,
                          })
                        }
                        required
                        className="bg-muted/20 border-border/50 h-14 rounded-2xl focus:ring-primary/20 focus:border-primary transition-all font-sans"
                      />
                    </div>
                    <div className="space-y-3">
                      <Label
                        htmlFor="registrationNumber"
                        className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1"
                      >
                        N° Immatriculation / Registre
                      </Label>
                      <Input
                        id="registrationNumber"
                        value={formData.registrationNumber}
                        onChange={(e) =>
                          setFormData({
                            ...formData,
                            registrationNumber: e.target.value,
                          })
                        }
                        className="bg-muted/20 border-border/50 h-14 rounded-2xl focus:ring-primary/20 focus:border-primary transition-all font-sans"
                      />
                    </div>
                    <div className="space-y-3 md:col-span-2">
                      <Label
                        htmlFor="address"
                        className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1"
                      >
                        Adresse du Siège
                      </Label>
                      <Input
                        id="address"
                        value={formData.address}
                        onChange={(e) =>
                          setFormData({ ...formData, address: e.target.value })
                        }
                        className="bg-white/5 border-white/10 h-14 rounded-2xl focus:ring-primary/20 focus:border-primary transition-all font-sans"
                      />
                    </div>
                    <div className="space-y-3">
                      <Label
                        htmlFor="phone"
                        className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1"
                      >
                        Téléphone
                      </Label>
                      <PhoneInput
                        value={formData.phone}
                        onChange={(val) => setFormData({ ...formData, phone: val })}
                      />
                    </div>
                    <div className="space-y-3">
                      <Label
                        htmlFor="email"
                        className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1"
                      >
                        Email par défaut
                      </Label>
                      <Input
                        id="email"
                        type="email"
                        value={formData.email}
                        onChange={(e) =>
                          setFormData({ ...formData, email: e.target.value })
                        }
                        className="bg-white/5 border-white/10 h-14 rounded-2xl focus:ring-primary/20 focus:border-primary transition-all font-sans"
                      />
                    </div>
                    <div className="space-y-3">
                      <Label
                        htmlFor="website"
                        className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1"
                      >
                        Site Web
                      </Label>
                      <Input
                        id="website"
                        value={formData.website}
                        onChange={(e) =>
                          setFormData({ ...formData, website: e.target.value })
                        }
                        className="bg-muted/20 border-border/50 h-14 rounded-2xl focus:ring-primary/20 focus:border-primary transition-all font-sans"
                      />
                    </div>

                    <div className="md:col-span-2 pt-4">
                      <h4 className="text-xs font-black uppercase tracking-widest text-primary mb-4">
                        Informations sur l’activité
                      </h4>
                      <div className="grid md:grid-cols-2 gap-6">
                        <div className="space-y-3">
                          <Label
                            htmlFor="sector"
                            className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1"
                          >
                            Secteur d’activité *
                          </Label>
                          <Input
                            id="sector"
                            value={formData.sector}
                            onChange={(e) =>
                              setFormData({
                                ...formData,
                                sector: e.target.value,
                              })
                            }
                            required
                            className="bg-muted/20 border-border/50 h-14 rounded-2xl focus:ring-primary/20 focus:border-primary transition-all font-sans"
                          />
                        </div>
                        <div className="space-y-3">
                          <Label
                            htmlFor="targetMarket"
                            className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1"
                          >
                            Marché cible
                          </Label>
                          <Input
                            id="targetMarket"
                            value={formData.targetMarket}
                            onChange={(e) =>
                              setFormData({
                                ...formData,
                                targetMarket: e.target.value,
                              })
                            }
                            className="bg-muted/20 border-border/50 h-14 rounded-2xl focus:ring-primary/20 focus:border-primary transition-all font-sans"
                          />
                        </div>
                        <div className="space-y-3 md:col-span-2">
                          <Label
                            htmlFor="description"
                            className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1"
                          >
                            {t("description")} *
                          </Label>
                          <Input
                            id="description"
                            value={formData.description}
                            onChange={(e) =>
                              setFormData({
                                ...formData,
                                description: e.target.value,
                              })
                            }
                            required
                            className="bg-muted/20 border-border/50 h-14 rounded-2xl focus:ring-primary/20 focus:border-primary transition-all font-sans"
                          />
                        </div>
                        <div className="space-y-3 md:col-span-2">
                          <Label
                            htmlFor="productsServices"
                            className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1"
                          >
                            {t("proposedProducts")} *
                          </Label>
                          <Input
                            id="productsServices"
                            value={formData.productsServices}
                            onChange={(e) =>
                              setFormData({
                                ...formData,
                                productsServices: e.target.value,
                              })
                            }
                            required
                            className="bg-muted/20 border-border/50 h-14 rounded-2xl focus:ring-primary/20 focus:border-primary transition-all font-sans"
                          />
                        </div>
                      </div>
                    </div>

                    <div className="md:col-span-2 pt-4">
                      <h4 className="text-xs font-black uppercase tracking-widest text-primary mb-4">
                        {t("financialInfo")}
                      </h4>
                      <div className="grid md:grid-cols-2 gap-6">
                        <div className="space-y-3">
                          <Label
                            htmlFor="annualRevenue"
                            className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1"
                          >
                            {t("annualRevenue")} *
                          </Label>
                          <Input
                            id="annualRevenue"
                            type="number"
                            value={formData.annualRevenue}
                            onChange={(e) =>
                              setFormData({
                                ...formData,
                                annualRevenue: e.target.value,
                              })
                            }
                            required
                            className="bg-muted/20 border-border/50 h-14 rounded-2xl focus:ring-primary/20 focus:border-primary transition-all font-sans"
                          />
                        </div>
                        <div className="space-y-3">
                          <Label
                            htmlFor="monthlyRevenue"
                            className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1"
                          >
                            Chiffre d’affaires mensuel
                          </Label>
                          <Input
                            id="monthlyRevenue"
                            type="number"
                            value={formData.monthlyRevenue}
                            onChange={(e) =>
                              setFormData({
                                ...formData,
                                monthlyRevenue: e.target.value,
                              })
                            }
                            className="bg-muted/20 border-border/50 h-14 rounded-2xl focus:ring-primary/20 focus:border-primary transition-all font-sans"
                          />
                        </div>
                      </div>
                    </div>

                    <div className="md:col-span-2 pt-4">
                      <h4 className="text-xs font-black uppercase tracking-widest text-primary mb-4">
                        Organisation
                      </h4>
                      <div className="grid md:grid-cols-2 gap-6">
                        <div className="space-y-3">
                          <Label
                            htmlFor="employeeCount"
                            className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1"
                          >
                            Nombre d’employés *
                          </Label>
                          <Input
                            id="employeeCount"
                            type="number"
                            value={formData.employeeCount}
                            onChange={(e) =>
                              setFormData({
                                ...formData,
                                employeeCount: e.target.value,
                              })
                            }
                            required
                            className="bg-muted/20 border-border/50 h-14 rounded-2xl focus:ring-primary/20 focus:border-primary transition-all font-sans"
                          />
                        </div>
                        <div className="space-y-3">
                          <Label
                            htmlFor="departments"
                            className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1"
                          >
                            Départements principaux *
                          </Label>
                          <Input
                            id="departments"
                            value={formData.departments}
                            onChange={(e) =>
                              setFormData({
                                ...formData,
                                departments: e.target.value,
                              })
                            }
                            required
                            placeholder="Ex: Direction, Comptabilité, Marketing"
                            className="bg-muted/20 border-border/50 h-14 rounded-2xl focus:ring-primary/20 focus:border-primary transition-all font-sans"
                          />
                        </div>
                      </div>
                    </div>

                    <div className="space-y-3 md:col-span-2 pt-6">
                      <Label className="text-[10px] font-black uppercase tracking-widest text-slate-500 ml-1">
                        Logo de l&apos;entreprise
                      </Label>
                      <div className="flex items-center gap-6 p-4 bg-white/5 border border-white/10 rounded-2xl">
                        <div className="size-20 rounded-xl bg-slate-900 border border-white/10 overflow-hidden flex items-center justify-center flex-shrink-0 relative">
                          {formData.logoUrl ? (
                            <Image
                              src={formData.logoUrl}
                              alt="Logo preview"
                              fill
                              className="object-contain"
                            />
                          ) : (
                            <Building2 className="size-8 text-slate-700" />
                          )}
                        </div>
                        <div className="space-y-2">
                          <Input
                            type="file"
                            accept="image/*"
                            onChange={handleLogoUpload}
                            className="bg-white/5 border-white/10 h-10 file:bg-primary file:text-primary-foreground file:border-0 file:rounded-lg file:mr-4 file:px-4 file:py-1 file:text-[10px] file:font-black file:uppercase cursor-pointer text-xs"
                          />
                          <p className="text-[10px] text-slate-500 font-medium tracking-tight">
                            Format recommandé : Carré, max 1Mo.
                          </p>
                        </div>
                      </div>
                    </div>
                  </div>
                  <DialogFooter className="pt-6 border-t border-white/10 gap-4">
                    <Button
                      type="button"
                      variant="outline"
                      onClick={() => setIsDialogOpen(false)}
                      className="rounded-xl px-8 h-12 uppercase text-[10px] font-black tracking-widest"
                    >
                      {t("cancel")}
                    </Button>
                    <Button
                      type="submit"
                      className="rounded-xl px-8 h-12 bg-primary hover:bg-primary/90 text-primary-foreground font-black uppercase text-[10px] tracking-widest gap-2 shadow-lg shadow-primary/20"
                    >
                      <Save className="w-4 h-4" />
                      {editingCompany ? t("updateStructure") : t("save")}
                    </Button>
                  </DialogFooter>
                </form>
              </DialogContent>
            </Dialog>
          </div>
        </div>

        {/* Stats Cards */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 animate-fade-in-up delay-200">
          {[
            {
              label: t("totalRevenue"),
              value: `${stats.totalRevenue.toLocaleString()} CFA`,
              icon: TrendingUp,
              color: "text-emerald-500",
              bg: "bg-emerald-500/10",
            },
            {
              label: t("totalLoss"),
              value: `${stats.totalLoss.toLocaleString()} CFA`,
              icon: TrendingDown,
              color: "text-rose-500",
              bg: "bg-rose-500/10",
            },
            {
              label: t("totalExpenses"),
              value: `${stats.totalExpenses.toLocaleString()} CFA`,
              icon: Receipt,
              color: "text-amber-500",
              bg: "bg-amber-500/10",
            },
            {
              label: t("totalClients"),
              value: stats.totalClients,
              icon: Users2,
              color: "text-blue-500",
              bg: "bg-blue-500/10",
            },
          ].map((stat, i) => (
            <div
              key={i}
              className="p-6 rounded-[2rem] bg-card/40 border border-white/5 backdrop-blur-2xl flex flex-col gap-3 group hover:border-primary/30 transition-all duration-500 shadow-xl overflow-hidden relative"
            >
              <div className={cn(
                "size-12 rounded-2xl flex items-center justify-center transition-transform group-hover:scale-110 relative z-10",
                stat.bg,
                stat.color
              )}>
                <stat.icon className="size-6" />
              </div>
              <div className="space-y-1 relative z-10">
                <p className="text-[10px] font-black uppercase tracking-widest text-slate-500">
                  {stat.label}
                </p>
                <p className="text-2xl font-black tracking-tighter">
                  {stat.value}
                </p>
              </div>
              <div className="absolute top-0 right-0 w-32 h-32 bg-primary/5 blur-[50px] rounded-full translate-x-1/2 -translate-y-1/2 group-hover:bg-primary/10 transition-colors" />
            </div>
          ))}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 animate-fade-in-up delay-100">
          {companies.length > 0 ? (
            companies.map((company) => (
              <Card
                key={company.id}
                className="group bg-card border border-border/40 shadow-sm hover:shadow-lg hover:border-primary/20 transition-all duration-300 rounded-3xl overflow-hidden flex flex-col h-full"
              >
                <CardContent className="p-8 pb-6 flex-1 flex flex-col">
                  <div className="flex justify-between items-start mb-6">
                    <div className="size-20 rounded-2xl bg-primary/5 border border-primary/10 p-4 flex items-center justify-center overflow-hidden shadow-sm group-hover:scale-105 transition-transform duration-300 relative">
                      {company.logoUrl ? (
                        <Image
                          src={company.logoUrl}
                          alt={company.name}
                          fill
                          className="object-contain"
                        />
                      ) : (
                        <Building2 className="size-10 text-primary/40" />
                      )}
                    </div>
                    <div className="flex gap-2">
                      <Button
                        variant="outline"
                        size="icon"
                        className={cn(
                          "h-10 w-10 rounded-xl transition-all",
                          activeCompanyId === company.id 
                            ? "bg-emerald-500/20 text-emerald-400 border-emerald-500/50" 
                            : "text-slate-400 border-white/10 hover:bg-white/5"
                        )}
                        onClick={() => handleSetActive(company.id)}
                        title={activeCompanyId === company.id ? "Entreprise active" : "Définir comme active"}
                      >
                        <CheckCircle2 className={cn("w-5 h-5", activeCompanyId === company.id ? "scale-110" : "opacity-50")} />
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-10 w-10 rounded-xl text-muted-foreground hover:text-primary hover:bg-primary/10 transition-colors"
                        onClick={() => openEdit(company)}
                      >
                        <Edit2 className="w-4 h-4" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-10 w-10 rounded-xl text-muted-foreground hover:text-destructive hover:bg-destructive/10 transition-colors"
                        onClick={() => handleDelete(company.id, company.name)}
                      >
                        <Trash2 className="w-4 h-4" />
                      </Button>
                    </div>
                  </div>

                  <div className="space-y-1 mb-8">
                    <h3 className="text-2xl font-black text-foreground tracking-tight leading-none group-hover:text-primary transition-colors">
                      {company.name}
                    </h3>
                    <p className="text-xs font-bold text-muted-foreground uppercase tracking-widest">
                      {company.legalForm || "Entreprise"} • {company.sector || "Secteur non spécifié"}
                    </p>
                  </div>

                  <div className="grid grid-cols-2 gap-8 pt-8 border-t border-border/10">
                    <div className="space-y-5">
                      <div className="space-y-1">
                        <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest block">
                          Identifiant Fiscal
                        </span>
                        <p className="text-sm font-semibold text-foreground">
                          {company.taxId || "—"}
                        </p>
                      </div>
                      <div className="space-y-1">
                        <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest block">
                          Contact E-mail
                        </span>
                        <p className="text-sm font-semibold text-foreground break-all">
                          {company.email || "—"}
                        </p>
                      </div>
                    </div>
                    <div className="space-y-5">
                      <div className="space-y-1">
                        <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest block">
                          Numéro Registre
                        </span>
                        <p className="text-sm font-semibold text-foreground">
                          {company.registrationNumber || "—"}
                        </p>
                      </div>
                      <div className="space-y-1">
                        <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest block">
                          Téléphone
                        </span>
                        <p className="text-sm font-semibold text-foreground">
                          {company.phone || "—"}
                        </p>
                      </div>
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))
          ) : (
            <div className="col-span-full py-20 text-center text-muted-foreground border-2 border-dashed border-border/50 rounded-2xl animate-fade-in-up">
              <Building2 className="w-12 h-12 mx-auto mb-4 opacity-20" />
              <p className="text-lg">Aucune entreprise trouvée</p>
              <Button
                variant="link"
                onClick={() => setIsDialogOpen(true)}
                className="mt-2 text-primary gap-1"
              >
                <Plus className="w-4 h-4" /> Ajouter votre première entreprise
              </Button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
